// Traduz o webhook da Evolution para o contrato da API do bot e
// descarta o que nao e pergunta de vendedor.
//
// Cada descarte devolve um motivo legivel: sem isso, depurar "o bot
// nao respondeu" vira adivinhacao na aba de execucoes.

const raiz = $input.first().json;
const body = raiz.body ?? raiz;
const data = body.data ?? {};
const chave = data.key ?? {};
const jid = chave.remoteJid ?? '';

function ignorar(motivo) {
  return [{ json: { processar: false, motivo } }];
}

// 1. Eco. A Evolution tambem notifica as mensagens que o PROPRIO bot
//    enviou. Sem este corte ele responde a si mesmo, em loop.
if (chave.fromMe === true) {
  return ignorar('mensagem enviada pelo proprio bot');
}

// 2. Grupos. O remoteJid de grupo nao e um telefone, e a whitelist da
//    API e por telefone — passaria direto para um 422.
if (jid.endsWith('@g.us')) {
  return ignorar('mensagem de grupo');
}

// 3. Status / broadcast.
if (jid.startsWith('status@') || jid.endsWith('@broadcast')) {
  return ignorar('status ou broadcast');
}

// 4. Texto. Mensagem simples vem em `conversation`; mensagem que cita
//    outra vem em `extendedTextMessage.text`. Audio, imagem e figurinha
//    nao tem texto e nao ha o que perguntar.
const mensagem = data.message ?? {};
const texto = (
  mensagem.conversation ??
  mensagem.extendedTextMessage?.text ??
  ''
).trim();

if (!texto) {
  return ignorar(`sem texto (tipo: ${data.messageType ?? 'desconhecido'})`);
}

// 5. Telefone. O jid chega como 5511999998888@s.whatsapp.net, as vezes
//    com sufixo de dispositivo (5511999998888:12@...). A API exige
//    E.164 sem '+', so digitos, 10 a 20 caracteres.
const remetente = jid.split('@')[0].split(':')[0].replace(/\D/g, '');
if (remetente.length < 10 || remetente.length > 20) {
  return ignorar(`remetente fora do formato (${remetente.length} digitos)`);
}

// 6. Id da mensagem. E a chave do dedupe: sem ele um reenvio da
//    Evolution viraria resposta duplicada para o vendedor.
const messageId = chave.id ?? '';
if (!messageId) {
  return ignorar('mensagem sem id (dedupe impossivel)');
}

return [{
  json: {
    processar: true,
    // Contrato da API: 1..1000 caracteres. Truncar e melhor que 422 —
    // o vendedor recebe resposta ao inves de silencio.
    pergunta: texto.slice(0, 1000),
    remetente,
    message_id: String(messageId).slice(0, 100),
    // Responder pela MESMA instancia que recebeu, em vez de fixar o
    // nome aqui: se um dia houver mais de uma, isto continua correto.
    instancia: body.instance ?? '',
    push_name: data.pushName ?? '',
  },
}];
